_BINARY_PRECEDENCE = {"+": 1, "-": 1, "*": 2, "/": 2}
_NEGATE = "~"
_PRECEDENCE = {**_BINARY_PRECEDENCE, _NEGATE: 3}


def _read_digits(text: str, start: int) -> int:
    index = start
    while index < len(text) and "0" <= text[index] <= "9":
        index += 1
    return index


def _tokenize(expression: str) -> list:
    tokens: list = []
    index = 0
    length = len(expression)
    while index < length:
        char = expression[index]
        if char == " ":
            index += 1
        elif "0" <= char <= "9":
            start = index
            index = _read_digits(expression, index)
            if index < length and expression[index] == ".":
                index += 1
                fraction_start = index
                index = _read_digits(expression, index)
                if index == fraction_start:
                    raise ValueError("小数点の後ろに数字がありません")
                tokens.append(float(expression[start:index]))
            else:
                tokens.append(int(expression[start:index]))
        elif char in "+-*/()":
            tokens.append(char)
            index += 1
        else:
            raise ValueError(f"知らない文字です: {char!r}")
    return tokens


def _to_postfix(tokens: list) -> list:
    output: list = []
    stack: list[str] = []
    expect_operand = True
    for token in tokens:
        is_symbol = isinstance(token, str)
        if expect_operand:
            if not is_symbol:
                output.append(token)
                expect_operand = False
            elif token == "-":
                stack.append(_NEGATE)
            elif token == "(":
                stack.append("(")
            else:
                raise ValueError("オペランドが必要な位置に演算子か括弧があります")
        else:
            if is_symbol and token in _BINARY_PRECEDENCE:
                while (
                    stack
                    and stack[-1] != "("
                    and _PRECEDENCE[stack[-1]] >= _PRECEDENCE[token]
                ):
                    output.append(stack.pop())
                stack.append(token)
                expect_operand = True
            elif is_symbol and token == ")":
                while stack and stack[-1] != "(":
                    output.append(stack.pop())
                if not stack:
                    raise ValueError("閉じ括弧に対応する開き括弧がありません")
                stack.pop()
            else:
                raise ValueError("演算子が必要な位置に数か開き括弧があります")
    if expect_operand:
        raise ValueError("式が途中で終わっています")
    while stack:
        top = stack.pop()
        if top == "(":
            raise ValueError("開き括弧が閉じられていません")
        output.append(top)
    return output


def _evaluate_postfix(postfix: list) -> int | float:
    values: list[int | float] = []
    for item in postfix:
        if not isinstance(item, str):
            values.append(item)
        elif item == _NEGATE:
            values.append(-values.pop())
        else:
            right = values.pop()
            left = values.pop()
            if item == "+":
                values.append(left + right)
            elif item == "-":
                values.append(left - right)
            elif item == "*":
                values.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError("0 で割りました")
                values.append(left / right)
    return values[0]


def evaluate(expression: str) -> int | float:
    tokens = _tokenize(expression)
    postfix = _to_postfix(tokens)
    return _evaluate_postfix(postfix)
